'use client';
import { useEffect, useId, useRef, useState, type KeyboardEvent, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useReducedMotion } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { useReflow } from '../lib/motion';
import { useHoverGlide } from '../lib/glide';
import '../designme.css';
import './search-input.css';

/** Something the box can find, like a Figma frame or a doc */
export interface SearchInputItem {
  icon: IconName;
  /** Its name. The part that matches the search is marked */
  label: string;
  /** Where it lives, like "Figma". A source filter keeps only the items whose source is its label */
  source: string;
}

/** A source you can narrow the search to by typing @ and its key, like @figma */
export interface SearchInputSource {
  key: string;
  /** Its name, like "Figma". It becomes the filter chip */
  label: string;
  icon: IconName;
}

export interface SearchInputProps {
  items: SearchInputItem[];
  /** Typing @ lists these, and picking one adds it as a filter chip */
  sources?: SearchInputSource[];
  /** Earlier searches, shown while the box is empty */
  recent?: string[];
  /** What is typed. Leave it out to let the box hold its own */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** The source filter, by label, or null. Backspace in an empty box removes it */
  scope?: string | null;
  defaultScope?: string | null;
  onScopeChange?: (scope: string | null) => void;
  /** Whether the list of results is open under the box. Focus opens it and leaving closes it when you leave it out */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** An answer from the agent, shown above the results once it has a word. Feed it as it grows and each new word fades in */
  answer?: string;
  /** Which items match the search. By default an item matches the whole search or any word longer than two letters */
  filter?: (item: SearchInputItem, search: string) => boolean;
  /** Called when a result is picked, by click or Enter */
  onSelect?: (item: SearchInputItem) => void;
  /** Called by Enter when no row is highlighted, with the search and the source filter */
  onSubmit?: (search: string, scope: string | null) => void;
  placeholder?: string;
  /** The key hint at the end of the empty box */
  shortcut?: string;
  /** The heading over the results. Defaults to "Results" */
  resultsLabel?: string;
  /** What the list says when nothing matches */
  emptyLabel?: string;
  className?: string;
}

// words too common to match on, as on designme.dev
const STOP = ['why', 'did', 'the', 'how', 'what', 'does'];
const wordsOf = (search: string) => search.toLowerCase().split(/[^a-z0-9.]+/).filter(w => w.length > 2 && !STOP.includes(w));
const matchAny = (item: SearchInputItem, search: string) => {
  const l = item.label.toLowerCase();
  return !search || l.includes(search.toLowerCase()) || wordsOf(search).some(w => l.includes(w));
};
// marks the first place the word appears
const marked = (label: string, word: string): ReactNode => {
  const at = word ? label.toLowerCase().indexOf(word.toLowerCase()) : -1;
  return at < 0 ? label : <>{label.slice(0, at)}<mark>{label.slice(at, at + word.length)}</mark>{label.slice(at + word.length)}</>;
};

type Row = { kind: 'recent'; search: string } | { kind: 'source'; source: SearchInputSource } | { kind: 'item'; item: SearchInputItem };

const rowKey = (r: Row) => r.kind === 'item' ? 'i:' + r.item.label + '|' + r.item.source : r.kind === 'recent' ? 'r:' + r.search : 's:' + r.source.key;

/** Search with source filters, recent searches and an answer from the agent. Type @ to filter by source. */
export function SearchInput({ items, sources = [], recent = [], value, defaultValue = '', onValueChange, scope, defaultScope = null, onScopeChange,
  open, defaultOpen = false, onOpenChange, answer, filter = matchAny, onSelect, onSubmit, placeholder = 'Search frames, files and docs',
  shortcut = '⌘K', resultsLabel = 'Results', emptyLabel = 'No matches. Press Enter to ask the agent', className }: SearchInputProps) {
  const [text, setText] = useControllable(value, defaultValue, onValueChange);
  const [sc, setScope] = useControllable(scope, defaultScope, onScopeChange);
  const [isOpen, setOpen] = useControllable(open, defaultOpen, onOpenChange);
  const v = text.trim();
  const root = useRef<HTMLDivElement>(null), input = useRef<HTMLInputElement>(null);
  const id = useId();

  // while the box is open, rows that were showing a moment ago glide to their new places as the answer comes and goes or the
  // results narrow, new rows and the answer fade in, and rows that no longer match fade where they were, so typing never
  // restarts the list; the list eases to its new height
  const [opens, setOpens] = useState(0), [wasOpen, setWasOpen] = useState(isOpen);
  if (wasOpen !== isOpen) { setWasOpen(isOpen); if (isOpen) setOpens(opens + 1); }

  const at = /@\w*$/.test(v) && sources.length ? v.split('@').pop()!.toLowerCase() : null;
  const found = items.filter(it => (!sc || it.source === sc) && filter(it, v));
  const word = wordsOf(v).find(w => found.some(it => it.label.toLowerCase().includes(w))) || v;
  const mode = at !== null ? 'sources' : !v && !sc ? 'recent' : 'results';
  const rows: Row[] = mode === 'sources' ? sources.filter(s => s.key.startsWith(at!)).map(source => ({ kind: 'source', source }))
    : mode === 'recent' ? recent.map(search => ({ kind: 'recent', search }))
    : found.map(item => ({ kind: 'item', item }));
  const paint = `${opens}|${text}|${sc}`;
  // places are read against the list, which opens from the box
  const list = useRef<HTMLDivElement>(null), field = useRef<HTMLDivElement>(null), pop = useRef<HTMLDivElement>(null);
  // Clean's one hover: a highlight that glides from row to row
  useHoverGlide(pop, '.dm-six-it');
  useReflow(pop, '.dm-six-res > [data-key]', { host: list });
  // the list opens under the box, or over it when the room under it in the window is too short, and keeps that side while it
  // is open, growing away from the box as the answer and the results come in
  const [up, setUp] = useState(false);
  useIsoLayoutEffect(() => {
    const f = field.current, p = pop.current; if (!isOpen || !f || !p) return;
    const b = f.getBoundingClientRect();
    setUp(b.bottom + p.offsetHeight + 12 > innerHeight && b.top - p.offsetHeight - 12 > innerHeight - b.bottom);
  }, [isOpen]);
  const lastH = useRef(0), grow = useRef<Animation | null>(null), reduce = useReducedMotion();
  useIsoLayoutEffect(() => {
    const el = list.current; if (!el) { lastH.current = 0; return; }
    const from = grow.current?.playState === 'running' ? el.getBoundingClientRect().height : lastH.current;
    grow.current?.cancel(); grow.current = null;
    const to = el.getBoundingClientRect().height; lastH.current = to;
    if (!isOpen || !from || Math.abs(from - to) < 1 || reduce || !el.animate) return;
    grow.current = el.animate([{ height: from + 'px', boxSizing: 'border-box', overflow: 'hidden' }, { height: to + 'px', boxSizing: 'border-box', overflow: 'hidden' }], { duration: 280, easing: 'cubic-bezier(.22,1,.36,1)' });
  });

  // the highlight only moves with the arrow keys, and starts afresh with each new list
  const [hi, setHi] = useState({ at: -1, for: paint });
  const cur = hi.for === paint && hi.at < rows.length ? hi.at : -1;

  // a click outside lowers the box, unless the cursor is still in it
  useEffect(() => {
    if (!isOpen) return;
    const down = (e: PointerEvent) => { if (!root.current?.contains(e.target as Node) && document.activeElement !== input.current) setOpen(false); };
    document.addEventListener('pointerdown', down);
    return () => document.removeEventListener('pointerdown', down);
  }, [isOpen, setOpen]);

  const pick = (row: Row) => {
    if (row.kind === 'recent') setText(row.search);
    else if (row.kind === 'source') { setScope(row.source.label); setText(text.replace(/@\w*$/, '')); }
    else onSelect?.(row.item);
  };
  const key = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault(); if (!isOpen) setOpen(true);
      if (rows.length) setHi({ at: cur < 0 ? (e.key === 'ArrowDown' ? 0 : rows.length - 1) : (cur + (e.key === 'ArrowDown' ? 1 : -1) + rows.length) % rows.length, for: paint });
    } else if (e.key === 'Enter') { if (cur >= 0) pick(rows[cur]); else onSubmit?.(v, sc); }
    // Escape closes the list and keeps the focus in the box; a second Escape clears it
    else if (e.key === 'Escape') { e.preventDefault(); if (isOpen) setOpen(false); else if (text || sc) { setText(''); setScope(null); } }
    else if (e.key === 'Backspace' && !text && sc) setScope(null);
  };
  // rows are picked on mousedown, so the cursor stays in the box
  const row = (r: Row, i: number, body: ReactNode) => {
    const k = rowKey(r);
    return (
      <button key={k} data-key={k} type="button" tabIndex={-1} id={`${id}-${i}`} role="option" aria-selected={i === cur} className={cx('dm-six-it', i === cur && 'dm-hl')}
        onMouseDown={ev => { ev.preventDefault(); pick(r); }}>{body}</button>
    );
  };

  const words = answer?.split(' ').filter(Boolean) ?? [];
  // the list shows while the box is open and has something to show
  const shown = isOpen && (mode !== 'recent' || rows.length > 0);
  return (
    <div data-dm="" ref={root} className={cx('dm-six', className)}>
      {/* the box: its edge steps up while it is in use */}
      <div ref={field} className={cx('dm-six-box', isOpen && 'dm-f')}>
        <div className="dm-six-in">
          <Icon name="search" size="xs" />
          <span className="dm-six-chips">
            {sc && <span key={sc} className="dm-six-ch dm-enter">{sc}<button type="button" aria-label="Remove filter" onMouseDown={e => { e.preventDefault(); setScope(null); }}><Icon name="x" size="xs" /></button></span>}
          </span>
          <input ref={input} placeholder={placeholder} aria-label="Search" spellCheck={false} value={text} role="combobox" aria-expanded={isOpen}
            aria-controls={`${id}-list`} aria-autocomplete="list" aria-activedescendant={isOpen && cur >= 0 ? `${id}-${cur}` : undefined}
            onChange={e => setText(e.target.value)} onFocus={() => setOpen(true)} onBlur={() => setOpen(false)} onKeyDown={key} />
          <span className="dm-kbd dm-six-k" hidden={!!v || !!sc}>{shortcut}</span>
          <button type="button" className="dm-ib dm-six-x" aria-label="Clear" hidden={!v && !sc} onMouseDown={e => { e.preventDefault(); setText(''); setScope(null); }}><Icon name="x" size="xs" /></button>
        </div>
      </div>
      <div ref={pop} className={cx('dm-pop dm-six-pop', shown && 'dm-open')} inert={!shown}
        style={up ? { top: 'auto', bottom: 'calc(100% + 6px)', ['--dm-origin' as string]: 'bottom left' } : { top: 'calc(100% + 6px)', ['--dm-origin' as string]: 'top left' }}>
        <div key={opens} ref={list} className="dm-six-res" id={`${id}-list`} role="listbox" aria-label="Results">
          {mode === 'sources' && <>
            <div className="dm-six-g" data-key="g">Filter by source</div>
            {rows.map((r, i) => r.kind === 'source' && row(r, i, <><span className="dm-ic"><Icon name={r.source.icon} size="xs" /></span>{r.source.label}<span className="dm-d">@{r.source.key}</span></>))}
          </>}
          {mode === 'recent' && !!rows.length && <>
            <div className="dm-six-g" data-key="g">Recent</div>
            {rows.map((r, i) => r.kind === 'recent' && row(r, i, <><span className="dm-ic"><Icon name="history" size="xs" /></span>{r.search}</>))}
          </>}
          {mode === 'results' && <>
            {words.length > 0 && <div className="dm-six-ans" data-key="ans"><Icon name="spark" size="xs" /><span>{words.map((w, i) => <span key={i} className="dm-w">{w} </span>)}</span></div>}
            {rows.length ? <>
              <div className="dm-six-g" data-key="g">{resultsLabel}</div>
              {rows.map((r, i) => r.kind === 'item' && row(r, i, <><span className="dm-ic"><Icon name={r.item.icon} size="xs" /></span><span>{marked(r.item.label, word)}</span><span className="dm-d">{r.item.source}</span></>))}
            </> : <div className="dm-six-g" data-key="g">{emptyLabel}</div>}
          </>}
        </div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Search input ---------- */
/* one field, as wide as the other single fields (the full width on a phone), with its suggestions in a list that opens from
   it: under it, or over it when the room under it is too short (placePop). Its script keeps the field and the open list
   centred in the stage together, the field gliding up as the list opens (centre()); no room is kept for the list. The
   field's glass, the rows' icons, the answer's spark and the group names share one column 12px in, and the words another */
.dm-six{position:relative;width:100%;max-width:var(--dm-field-w);margin:0 auto}
.dm-six-box{background:var(--dm-surface);border-radius:var(--dm-r-field);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.dm-six-box{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
/* the edge steps up while the field is in use (it has the focus, or the preview types in it); nothing else changes */
.dm-six-box.dm-f{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* 12px in at both ends: the magnifier on the left, and on the right the ⌘K key or the clear button's box (check-rules R2, 27 Nov) */
.dm-six-in{display:flex;align-items:center;gap:var(--dm-s-2);height:var(--dm-field-h);padding:0 var(--dm-s-3);color:var(--dm-muted)}
.dm-six-in input{flex:1;min-width:0;height:100%;border:0;outline:0;background:transparent;font:inherit;font-size:13.5px;color:var(--dm-fg)}
/* (its words start right after the glass, as the rows' words do) */
.dm-six .dm-six-in input{padding:0}
.dm-six-in input::placeholder{color:var(--dm-muted)}
.dm-six-chips{display:flex;gap:var(--dm-s-1)}
.dm-six-chips:empty{display:none}
.dm-six-ch{display:inline-flex;align-items:center;gap:2px;height:24px;padding:0 2px 0 var(--dm-s-2);border-radius:var(--dm-r-tag);background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent));font-size:12px;font-weight:500;white-space:nowrap}
.dm-six-ch button{width:20px;height:20px;border-radius:50%;display:grid;place-items:center;opacity:.7;transition:opacity var(--dm-t-fast),background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-six-ch button:hover{opacity:1;background:color-mix(in srgb,currentColor 12%,transparent)}}
@supports (corner-shape:squircle){.dm-six-ch{corner-shape:squircle;border-radius:var(--dm-r-tag-sq)}}
/* the key hint and the clear button's cross end 14px in, where the rows' sources end */
.dm-six-x{width:24px;height:24px}
/* nothing in it grows or shrinks when pressed */
.dm-six :is(.dm-ib,.dm-pill):active,:root[data-style="clean"] .dm-six .dm-ib:active,:root [data-style="clean"] .dm-six .dm-ib:active,:root [data-style="clean"].dm-six .dm-ib:active{transform:none}
/* the list: one family with the field (owner, 21 Nov: "the input is different shape than the dropdown"): as wide as it, 6px
   under it, with the field's corners. Its rows sit 6px in, their corners the list's less those 6px, so their icons and words
   fall on the field's columns and their sources end where the field's cross does. (The 6px are the results' own padding, so
   the answer above them can run to the list's edges) */
.dm-six-pop{left:0;right:0;min-width:0;padding:0;border-radius:var(--dm-r-field)}
@supports (corner-shape:squircle){.dm-six-pop{border-radius:var(--dm-r-field-sq)}}
.dm-six-res{position:relative;padding:6px}
.dm-six-g{font-size:11.5px;color:var(--dm-muted);padding:var(--dm-s-2) var(--dm-s-2) var(--dm-s-1) 6px}
.dm-six-it{display:flex;align-items:center;gap:var(--dm-s-2);width:100%;padding:7px var(--dm-s-2) 7px 6px;border-radius:calc(var(--dm-r-field) - 4px);font-size:13px;text-align:left;transition:background .15s}
@supports (corner-shape:squircle){.dm-six-it{border-radius:calc(var(--dm-r-field-sq) - 6px)}}
.dm-six-it.dm-hl{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dm-six-it:hover{background:var(--dm-row)}}
.dm-six-it .dm-ic{color:var(--dm-muted);display:grid;flex:none}
.dm-six-it .dm-d{margin-left:auto;padding-left:var(--dm-s-2);font-size:12px;color:var(--dm-muted);transition:color .15s}
/* on a highlighted row's grey the source steps up, so it keeps 4.5:1 and APCA Lc 60 in dark mode */
@media (hover:hover) and (pointer:fine){.dm-six-it:is(:hover,.dm-hl) .dm-d{color:var(--dm-fg2)}}
.dm-six-it mark{background:transparent;color:var(--dm-accent-fg,var(--dm-accent));font-weight:500}
/* the agent's answer is the list's head section (owner, 21 Nov: "too stark"): no box and no tint, running to the list's edges
   with a hairline under it. Its spark is on the icons' column, in the accent's mark colour, the only colour in it; its words
   are on the words' column, in the text colour at the rows' size. It grows with the list as its words come in. Clean makes
   it the list's off-white head strip, with the spark muted */
.dm-six-ans{display:flex;gap:var(--dm-s-2);margin:-6px -6px 6px;padding:10px 14px 10px 12px;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13px;line-height:1.5;color:var(--dm-fg)}
.dm-six-ans>svg{color:var(--dm-accent-mark);flex:none;margin-top:3px}
.dm-six-ans .dm-w{animation:dm-sxw .4s var(--dm-ease) both}
.dm-six-ans .dm-w.dm-done{animation:none}
@keyframes dm-sxw{from{opacity:0;filter:blur(3px)}}
@keyframes dm-sxwc{from{opacity:0}}
/* Clean: the list has the field's 10px corners and its rows follow them, 6px in (4px corners); the answer is the off-white
   head strip under the list's top corners, with a full hairline under it; the rows' hover is Clean's quiet fill at its own
   ease; the filter is a tag with rounded corners, not a pill; new words fade in without a blur */
:root[data-style="clean"] .dm-six-it,:root [data-style="clean"] .dm-six-it,:root [data-style="clean"].dm-six-it{border-radius:calc(var(--dm-r-field) - 6px);transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dm-six-ans,:root [data-style="clean"] .dm-six-ans,:root [data-style="clean"].dm-six-ans{background:var(--dm-strip);border-bottom-color:var(--dm-line);border-radius:var(--dm-r-field) var(--dm-r-field) 0 0}
:root[data-style="clean"] .dm-six-ans>svg,:root [data-style="clean"] .dm-six-ans>svg,:root [data-style="clean"].dm-six-ans>svg{color:var(--dm-muted)}
:root[data-style="clean"] .dm-six-ch,:root [data-style="clean"] .dm-six-ch,:root [data-style="clean"].dm-six-ch{border-radius:var(--dm-r-sm)}
:root[data-style="clean"] .dm-six-ans .dm-w:not(.dm-done),:root [data-style="clean"] .dm-six-ans .dm-w:not(.dm-done),:root [data-style="clean"].dm-six-ans .dm-w:not(.dm-done){animation-name:dm-sxwc;animation-duration:var(--dm-t)}
